public class RedesignBenchmark {
    static volatile int sink;
    static String original(int fields){String s="";for(int i=0;i<fields;i++)s+="FIELD"+i+" ";return s;}
    static String redesigned(int fields){StringBuilder b=new StringBuilder();for(int i=0;i<fields;i++)b.append("FIELD").append(i).append(' ');return b.toString();}
    static long run(boolean improved,int fields,int repeats){long start=System.nanoTime();int total=0;for(int r=0;r<repeats;r++)total+=(improved?redesigned(fields):original(fields)).length();sink=total;return (System.nanoTime()-start)/repeats;}
    public static void main(String[] args){int[] sizes={10,50,200,500};int repeats=2000;System.out.println("Fields,Original String+ average ns,Redesigned StringBuilder average ns");for(int n:sizes){long old=run(false,n,repeats),fresh=run(true,n,repeats);System.out.println(n+","+old+","+fresh);}System.out.println("Diagnosis: repeated String concatenation creates intermediate immutable strings and repeatedly copies existing characters.");System.out.println("Objective: reduce repeated copying and temporary objects while producing identical ticket text.");System.out.println("Redesign: one StringBuilder per ticket, append each field, then convert once to String.");System.out.println("Expected complexity: repeated concatenation can copy O(n^2) total characters for n similarly sized fields; StringBuilder append is amortized O(n) total work, with O(n) output storage.");System.out.println("Trade-off: StringBuilder is mutable and not thread-safe; create a separate builder per ticket rather than sharing it across threads.");}
}
